const mySalesCounts = `-- name: MySalesCounts :one

SELECT
    (SELECT count(*) FROM leads l JOIN lead_stages s ON s.id = l.stage_id
      WHERE l.owner_id = $1 AND s.kind = 'open')::int AS open_leads,
    (SELECT count(*) FROM leads l JOIN lead_stages s ON s.id = l.stage_id
      WHERE l.owner_id = $1 AND s.kind = 'open' AND l.first_contacted_at IS NULL)::int AS untouched_leads,
    (SELECT count(*) FROM lead_follow_ups f
      WHERE f.owner_id = $1 AND f.done_at IS NULL AND f.due_at < $2::timestamptz)::int AS follow_ups_today,
    (SELECT count(*) FROM lead_follow_ups f
      WHERE f.owner_id = $1 AND f.done_at IS NULL AND f.due_at < now())::int AS follow_ups_overdue,
    (SELECT count(*) FROM leads l JOIN lead_stages s ON s.id = l.stage_id
      WHERE l.owner_id IS NULL AND l.pullable AND s.kind = 'open'
        AND (l.team_id IS NULL OR l.team_id = $3))::int AS pool_leads,
    (SELECT count(*) FROM admissions a
      WHERE a.counsellor_id = $1 AND a.status <> 'cancelled' AND a.created_at >= $4::timestamptz)::int AS admissions_month,
    (SELECT COALESCE(sum(p.amount_paise), 0) FROM payments p JOIN admissions a ON a.id = p.admission_id
      WHERE a.counsellor_id = $1 AND p.status = 'approved' AND p.approved_at >= $4::timestamptz)::bigint AS collected_month,
    (SELECT COALESCE(sum(e.amount_paise), 0) FROM commission_entries e
      WHERE e.counsellor_id = $1 AND e.month = $5::date)::bigint AS commission_month
`

type MySalesCountsParams struct {
	UserID     *uuid.UUID `json:"user_id"`
	DayEnd     time.Time  `json:"day_end"`
	TeamID     *uuid.UUID `json:"team_id"`
	MonthStart time.Time  `json:"month_start"`
	Month      time.Time  `json:"month"`
}

type MySalesCountsRow struct {
	OpenLeads        int32 `json:"open_leads"`
	UntouchedLeads   int32 `json:"untouched_leads"`
	FollowUpsToday   int32 `json:"follow_ups_today"`
	FollowUpsOverdue int32 `json:"follow_ups_overdue"`
	PoolLeads        int32 `json:"pool_leads"`
	AdmissionsMonth  int32 `json:"admissions_month"`
	CollectedMonth   int64 `json:"collected_month"`
	CommissionMonth  int64 `json:"commission_month"`
}

// ───────────── Dashboards ─────────────
func (q *Queries) MySalesCounts(ctx context.Context, arg MySalesCountsParams) (MySalesCountsRow, error) {
	row := q.db.QueryRow(ctx, mySalesCounts,
		arg.UserID,
		arg.DayEnd,
		arg.TeamID,
		arg.MonthStart,
		arg.Month,
	)
	var i MySalesCountsRow
	err := row.Scan(
		&i.OpenLeads,
		&i.UntouchedLeads,
		&i.FollowUpsToday,
		&i.FollowUpsOverdue,
		&i.PoolLeads,
		&i.AdmissionsMonth,
		&i.CollectedMonth,
		&i.CommissionMonth,
	)
	return i, err
}

